FATTORE_TIPO_MELARIO = {'standard': 1.0, 'tre_quarti': 0.75, 'meta': 0.5}


def backfill_produzione_per_colonia(apps, schema_editor):
    """Riempie i dati di produzione per colonia delle smielature già registrate.

    - `colonia`: la colonia su cui il melario si trova oggi (miglior stima
      disponibile per il passato).
    - `kg_miele`: i kg della smielatura divisi fra i melari in proporzione ai
      telaini, corretti per il formato. Solo dove erano vuoti.
    """
    from decimal import Decimal, ROUND_HALF_UP
    Smielatura = apps.get_model('core', 'Smielatura')
    SmielaturaMelario = apps.get_model('core', 'SmielaturaMelario')
    cent = Decimal('0.01')

    for sm in Smielatura.objects.all().iterator():
        righe = list(
            SmielaturaMelario.objects.filter(smielatura_id=sm.pk)
            .select_related('melario').order_by('id')
        )
        if not righe:
            continue
        for r in righe:
            if r.colonia_id is None and r.melario.colonia_id:
                SmielaturaMelario.objects.filter(pk=r.pk).update(
                    colonia_id=r.melario.colonia_id)

        if any(r.kg_miele is not None for r in righe):
            continue  # già attribuiti: non si toccano
        pesi = []
        for r in righe:
            telaini = r.melario.numero_telaini or 0
            fattore = FATTORE_TIPO_MELARIO.get(r.melario.tipo_melario, 1.0)
            pesi.append(telaini * fattore if telaini > 0 else fattore)
        somma = sum(pesi) or 1.0
        totale = Decimal(str(sm.quantita_miele or 0))
        assegnati = Decimal('0')
        for i, (r, peso) in enumerate(zip(righe, pesi)):
            if i == len(righe) - 1:
                kg = totale - assegnati
            else:
                kg = (totale * Decimal(str(peso)) / Decimal(str(somma))).quantize(
                    cent, rounding=ROUND_HALF_UP)
                assegnati += kg
            SmielaturaMelario.objects.filter(pk=r.pk).update(
                kg_miele=max(Decimal('0'), kg))


